import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_ANIMAL, MODELO_REFUGIO } from '../../models/refugio-animal.model.mjs';

export async function buscarRefugioRepository(refugioId) {
  const { Item } = await MODELO_REFUGIO.build(EntityRepository).get(
    { refugioId },
    { consistent: true }
  );
  return Item ?? null;
}

export async function consultarRefugioRepository(refugioId, minimo) {
  const { Items = [] } = await MODELO_ANIMAL.build(EntityRepository).query(
    { index: 'PorRefugio', partition: refugioId },
    { filters: { Animal: { attr: 'edadMeses', gte: minimo } } }
  );
  return Items;
}

import { trasladarAnimalService } from './service.mjs';

export async function handler(event) {
  const animalId = Number(event.pathParameters.animalId);
  const { refugioId } = JSON.parse(event.body);
  const resultado = await trasladarAnimalService(animalId, refugioId);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { trasladarAnimalRepository } from './repository.mjs';
import { buscarRefugioRepository } from '../../refugios/consultar/repository.mjs';

export async function trasladarAnimalService(animalId, refugioId) {
  const refugio = await buscarRefugioRepository(refugioId);
  if (!refugio) throw new Error('Refugio no encontrado');
  return trasladarAnimalRepository(animalId, refugioId);
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_ANIMAL, MODELO_REFUGIO } from '../../models/refugio-animal.model.mjs';

export async function trasladarAnimalRepository(animalId, refugioId) {
  const { Attributes } = await MODELO_ANIMAL.build(EntityRepository).update(
    { animalId, refugioId },
    {
      condition: { attr: 'animalId', exists: true },
      returnValues: 'ALL_NEW'
    }
  );
  return Attributes;
}

import { consultarRefugioService } from './service.mjs';

export async function handler(event) {
  const refugioId = Number(event.pathParameters.refugioId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarRefugioService(refugioId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarRefugioRepository, consultarRefugioRepository } from './repository.mjs';

export async function consultarRefugioService(refugioId, minimo) {
  const refugio = await buscarRefugioRepository(refugioId);
  if (!refugio) throw new Error('Refugio no encontrado');
  const animales = await consultarRefugioRepository(refugioId, minimo);
  return { refugio, animales };
}

